    $config=['site'=>'idem-test','idempotency'=>['connection'=>'db','epoch'=>$e->epoch,'integrity_keys'=>'keys','authority'=>'current','management_guard'=>'manager','policy'=>['maximum_entries'=>5]]];$calls=0;$services=['db'=>$e->pdo,'keys'=>$e->keys,'current'=>static function()use(&$calls):bool{++$calls;return true;},'manager'=>static function()use(&$calls):bool{++$calls;return true;}];
    $queries=$e->pdo->queries;$factory=Security::fromArray($config,$services,$e->clock);$s=$factory->idempotency();$checks=array_column($factory->diagnose(null,true),null,'check');Check::same($queries,$e->pdo->queries);Check::same(0,$calls);
    foreach(['connection','integrity_keys','authority','management_guard','schema_durability','request_identity','current_business','transactional_handler','key_separation','recovery_retention','transport_timeout'] as $item){Check::same('manual',$checks['idempotency.'.$item]['status']);}
